import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  // Create plane geometry with aspect ratio 512/320 = 1.6
  const width = 1.6;
  const height = 1;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture (cached resource)
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply transformation from config
  mesh.position.set(
    config.scenePosition.x,
    config.scenePosition.y,
    config.scenePosition.z
  );

  mesh.rotation.set(
    config.sceneRotation.x,
    config.sceneRotation.y,
    config.sceneRotation.z
  );

  mesh.scale.set(
    config.sceneScale.x,
    config.sceneScale.y,
    config.sceneScale.z
  );

  // Apply cinematic primitives if any
  if (config.cinematicPrimitives && config.cinematicPrimitives.length > 0) {
    config.cinematicPrimitives.forEach(primitive => {
      ctx.primitives[primitive.name](mesh, primitive.params);
    });
  }

  // Setup userData with handlers and cleanup
  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
